-- Files made outside Orbita (images and short videos) can be uploaded onto a post, next to the images generated by the
-- visuals module. They share the post_media table and the private post-media bucket: read access follows
-- can_access_client, and only the server (service role) writes rows and files. The browser uploads with a signed URL
-- that the server issues after checking who is asking, and the server verifies the file before recording it.
alter table public.post_media
  add column kind text not null default 'image' check (kind in ('image','video')),
  add column source text not null default 'generated' check (source in ('generated','uploaded')),
  add column uploaded_by uuid references auth.users(id) on delete set null,
  add column name text check (name is null or char_length(name) <= 120);

-- Images (png, jpeg, webp) and short videos (mp4, quicktime), up to 50 MB each (the Supabase free-plan ceiling).
update storage.buckets
   set public = false, file_size_limit = 52428800,
       allowed_mime_types = array['image/png','image/jpeg','image/webp','video/mp4','video/quicktime']
 where id = 'post-media';
